456	// Cursor broadcasting system - 20Hz server updates
457	function startCursorBroadcasting(gameId) {
458	  if (cursorUpdateIntervals[gameId]) {
459	    return; // Already broadcasting for this game
460	  }
461	  
462	  cursorUpdateIntervals[gameId] = setInterval(() => {
463	    if (!(gameId in games)) {
464	      // Game no longer exists, stop broadcasting
465	      clearInterval(cursorUpdateIntervals[gameId]);
466	      delete cursorUpdateIntervals[gameId];
467	      return;
468	    }
469	    
470	    const game = games[gameId];
471	    const cursors = game.getAllCursors();
472	    
473	    // Only broadcast if there are cursors to send
474	    if (Object.keys(cursors).length > 0) {
475	      io.to(gameId).emit('cursor_batch_update', { cursors });
476	    }
477	  }, CURSOR_UPDATE_INTERVAL);
478	}
479	
480	function stopCursorBroadcasting(gameId) {
481	  if (cursorUpdateIntervals[gameId]) {
482	    clearInterval(cursorUpdateIntervals[gameId]);
483	    delete cursorUpdateIntervals[gameId];
484	  }
485	}
486	
487	// Clean up inactive games
488	function cleanupInactiveGames() {
489	  const now = Date.now();
490	  Object.entries(games).forEach(([gameId, game]) => {
491	    if (now - game.lastActivity.getTime() > INACTIVE_GAME_TIMEOUT) {
492	      console.log(`Removing inactive game: ${gameId}`);
493	      stopCursorBroadcasting(gameId);
494	      delete games[gameId];
495	    }
496	  });
497	}
498	
499	setInterval(cleanupInactiveGames, 5 * 60 * 1000); // Clean up every 5 minutes
500	
