* {
    margin: 0;
    padding: 0;
    box-sizing: border-box; /* Include padding and borders in the element's total width and height */
}

html, body {
    margin: 0;
    padding: 0;
    width: 100%;
    height: 100%;
}

body {
    background: linear-gradient(0deg, rgb(36, 184, 22) 0%, rgb(122, 82, 8) 10%);
    transition-duration: 1s; /* Smooth transition if properties change */
}

.wrapper {
    height: 100vh; /* Ensures the wrapper covers the entire viewport height */
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    width: 100%; /* Make sure the wrapper takes the full width */
    max-width: 1000px; /* Set max-width if needed */
    margin: 0 auto; /* Center the wrapper if max-width is set */
}

.wrapper h2 {
    color: #007bff;
    margin-bottom: 20px;
    font-size: 5rem;
    text-align: center; /* Center the text */
}

form ul {
    list-style: none;
    padding: 0;
    width: 100%; /* Ensures the form ul takes the full width */
}

form ul li {
    margin: 32px 0;
    width: 100%; /* Adjust width as needed */
}

form ul li label {
    color: #7e2424;
    font-family: "Roboto", sans-serif;
    font-size: 40px;
    font-weight: bold;
    position: relative;
    text-transform: uppercase;
    width: 100%;
    display: block;
    text-align: center;
}

form ul li button {
    padding: 0 10px;
    width: 100%; /* Stretch button to full width */
}

input {
    height: 46px;
    display: block;
    font-size: 28px;
    background-color: rgba(25, 143, 133, 0.3);
    border: 2px rgba(255, 255, 255, .7) solid;
    font-family: "Bold";
    color: rgba(255, 255, 255, .8);
    width: 100%; /* Make input take full width of its parent */
    max-width: 100%; /* Ensures it doesn't exceed the parent width */
}

