3	// Standard Normal variate using Box-Muller transform.
4	export function gaussianRandom(mean=0, stdev=1) {
5	    const u = 1 - Math.random(); // Converting [0,1) to (0,1]
6	    const v = Math.random();
7	    const z = Math.sqrt( -2.0 * Math.log( u ) ) * Math.cos( 2.0 * Math.PI * v );
8	    // Transform to the desired mean and standard deviation:
9	    return Math.round(z * stdev + mean);
10	}
