12	export function lerp(start, end, t) {
13	    return start * (1 - t) + end * t;
14	}
15	
16	export function easeInOutCubic(t) {
17	    return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
