50	            btn.style.color = 'white';
51	            btn.style.border = 'none';
52	            btn.style.borderRadius = '5px';
53	            btn.style.cursor = 'pointer';
54	            btn.onclick = () => {
55	                button.callback();
56	                document.body.removeChild(popup);
57	            };
58	            buttonContainer.appendChild(btn);
59	        });
60	        
61	        popup.appendChild(buttonContainer);
62	    }
63	    
64	    document.body.appendChild(popup);
65	
66	    if (duration > 0) {
67	        setTimeout(() => {
68	            if (document.body.contains(popup)) {
69	                document.body.removeChild(popup);
70	            }
71	        }, duration);
72	    }
73	    
74	    return popup;
75	}
