77	export function createPlayerSelector(players, excludePlayer, callback) {
78	    const overlay = document.createElement('div');
79	    overlay.style.position = 'fixed';
80	    overlay.style.top = '0';
81	    overlay.style.left = '0';
82	    overlay.style.width = '100%';
83	    overlay.style.height = '100%';
84	    overlay.style.background = 'rgba(0, 0, 0, 0.8)';
85	    overlay.style.zIndex = '1001';
86	    overlay.style.display = 'flex';
87	    overlay.style.alignItems = 'center';
88	    overlay.style.justifyContent = 'center';
89	
90	    const selector = document.createElement('div');
91	    selector.style.background = 'white';
92	    selector.style.padding = '30px';
93	    selector.style.borderRadius = '15px';
94	    selector.style.textAlign = 'center';
95	    selector.innerHTML = '<h2 style="margin-top: 0;">Choose a Player</h2>';
96	
97	    const availablePlayers = players.filter(player => player !== excludePlayer);
98	    
99	    availablePlayers.forEach(player => {
100	        const playerBtn = document.createElement('button');
101	        playerBtn.textContent = player;
102	        playerBtn.style.display = 'block';
103	        playerBtn.style.width = '200px';
104	        playerBtn.style.margin = '10px auto';
105	        playerBtn.style.padding = '15px';
106	        playerBtn.style.background = '#FF6B6B';
107	        playerBtn.style.color = 'white';
108	        playerBtn.style.border = 'none';
109	        playerBtn.style.borderRadius = '8px';
110	        playerBtn.style.cursor = 'pointer';
111	        playerBtn.style.fontSize = '16px';
112	        
113	        playerBtn.onclick = () => {
114	            callback(player);
115	            document.body.removeChild(overlay);
116	        };
117	        
118	        selector.appendChild(playerBtn);
119	    });
120	
121	    overlay.appendChild(selector);
122	    document.body.appendChild(overlay);
123	    
124	    return overlay;
125	}
126	
127	export function createTextInput(prompt, callback, timeout = 30000) {
128	    const overlay = document.createElement('div');
129	    overlay.style.position = 'fixed';
130	    overlay.style.top = '0';
131	    overlay.style.left = '0';
132	    overlay.style.width = '100%';
133	    overlay.style.height = '100%';
134	    overlay.style.background = 'rgba(0, 0, 0, 0.8)';
135	    overlay.style.zIndex = '1001';
136	    overlay.style.display = 'flex';
137	    overlay.style.alignItems = 'center';
138	    overlay.style.justifyContent = 'center';
139	
140	    const inputBox = document.createElement('div');
141	    inputBox.style.background = 'white';
142	    inputBox.style.padding = '30px';
143	    inputBox.style.borderRadius = '15px';
144	    inputBox.style.textAlign = 'center';
145	    
146	    inputBox.innerHTML = `
147	        <h2 style="margin-top: 0;">${prompt}</h2>
148	        <input type="text" id="text-input" style="width: 250px; padding: 10px; font-size: 16px; margin: 10px;">
149	        <br>
150	        <button id="submit-btn" style="padding: 10px 20px; background: #4CAF50; color: white; border: none; border-radius: 5px; cursor: pointer;">Submit</button>
151	        <div id="timer" style="margin-top: 15px; font-size: 18px; color: #FF6B6B;"></div>
152	    `;
153	
154	    const input = inputBox.querySelector('#text-input');
155	    const submitBtn = inputBox.querySelector('#submit-btn');
156	    const timerDiv = inputBox.querySelector('#timer');
157	    
158	    let timeLeft = timeout / 1000;
159	    const timer = setInterval(() => {
160	        timeLeft--;
161	        timerDiv.textContent = `Time remaining: ${timeLeft}s`;
162	        
163	        if (timeLeft <= 0) {
164	            clearInterval(timer);
165	            callback('');
166	            document.body.removeChild(overlay);
167	        }
168	    }, 1000);
169	
170	    const handleSubmit = () => {
171	        clearInterval(timer);
172	        callback(input.value);
173	        document.body.removeChild(overlay);
174	    };
175	
176	    submitBtn.onclick = handleSubmit;
177	    input.addEventListener('keypress', (e) => {
178	        if (e.key === 'Enter') {
179	            handleSubmit();
180	        }
181	    });
182	
183	    overlay.appendChild(inputBox);
184	    document.body.appendChild(overlay);
185	    
186	    input.focus();
187	    return overlay;
188	}
189	
190	export function createReactionPrompt(message, targetZone, callback) {
191	    const popup = createPopup(message, 0);
192	    
193	    let reacted = false;
194	    const startTime = Date.now();
195	    
196	    const checkReaction = (event) => {
197	        if (reacted) return;
198	        
199	        const rect = document.querySelector('#gameCanvas').getBoundingClientRect();
200	        const x = event.clientX - rect.left;
201	        const y = event.clientY - rect.top;
202	        
203	        let inZone = false;
204	        if (targetZone === 'top') {
205	            inZone = y < rect.height * 0.2;
206	        } else if (targetZone === 'bottom') {
207	            inZone = y > rect.height * 0.8;
208	        }
209	        
210	        if (inZone) {
211	            reacted = true;
212	            const reactionTime = Date.now() - startTime;
213	            callback(reactionTime);
214	            document.body.removeChild(popup);
215	            document.removeEventListener('mousemove', checkReaction);
216	        }
217	    };
218	    
219	    document.addEventListener('mousemove', checkReaction);
220	    
221	    return popup;
222	}
223	
224	export function createDrinkingPrompt(playerName, callback) {
225	    const popup = createPopup(`${playerName}, click when you're done drinking!`, 0, [
226	        {
227	            text: 'Done Drinking',
228	            callback: callback
229	        }
230	    ]);
231	    
232	    return popup;
233	}

