405	// ── createReactionPrompt ──────────────────────────────────────
406	// Shows a popup instructing the player to move mouse to a zone.
407	// Monitors mousemove on the canvas to detect if player reacted.
408	export function createReactionPrompt(message, targetZone, callback) {
409	    const overlay = createPopup(message, 0);
410	
411	    let reacted = false;
412	    const startTime = Date.now();
413	
414	    const checkReaction = (event) => {
415	        if (reacted) return;
416	
417	        const canvas = document.querySelector('#gameCanvas');
418	        if (!canvas) return;
419	
420	        const rect = canvas.getBoundingClientRect();
421	        const x = event.clientX - rect.left;
422	        const y = event.clientY - rect.top;
423	
424	        let inZone = false;
425	        if (targetZone === 'top')    inZone = y < rect.height * 0.2;
426	        if (targetZone === 'bottom') inZone = y > rect.height * 0.8;
427	
428	        if (inZone) {
429	            reacted = true;
430	            const reactionTime = Date.now() - startTime;
431	            callback(reactionTime);
432	            if (document.body.contains(overlay)) document.body.removeChild(overlay);
433	            document.removeEventListener('mousemove', checkReaction);
434	        }
435	    };
436	
437	    document.addEventListener('mousemove', checkReaction);
438	    return overlay;
439	}
