174	
175	function setupCursorCanvas() {
176	    cursorCanvas = document.createElement('canvas');
177	    cursorCanvas.width = canvas.width;
178	    cursorCanvas.height = canvas.height;
179	    cursorCanvas.style.position = 'absolute';
180	    cursorCanvas.style.left = canvas.offsetLeft + 'px';
181	    cursorCanvas.style.top = canvas.offsetTop + 'px';
182	    cursorCanvas.style.pointerEvents = 'none'; // Allow clicks to pass through
183	    document.body.appendChild(cursorCanvas);
184	    cursorCtx = cursorCanvas.getContext('2d');
185	}
186	
187	function gameLoop() {
188	    const currentTime = Date.now();
189	    
190	    // Update player cursor positions at 60Hz
191	    updatePlayerPositions();
192	    
193	    // Render cursors at 60Hz but only if enough time has passed
194	    if (currentTime - lastCursorRenderTime >= CLIENT_REFRESH_RATE) {
195	        drawPlayers();
196	        lastCursorRenderTime = currentTime;
197	    }
198	    
199	    requestAnimationFrame(gameLoop);
200	}
201	
202	function checkAllImagesLoaded() {
203	    if (imagesLoaded === totalImages) {
204	        drawTable();
205	    }
206	}
207	
208	function get_game_state() {
209	
210	    console.log(`Game id in get_game_state ${gameId}`);
211	
212	    fetch('/get_game_state', {
213	        method: 'POST',
214	        headers: {'Content-Type': 'application/json'},
215	        body: JSON.stringify({game_id: gameId, player_name: client})
216	    })
217	    .then(response => response.json())
218	    .then(data => {
219	        if (data.success) {
220	            updateGameState(data.game);
221	        }
222	    });
223	}
224	
225	function createGame() {
226	    client = document.getElementById('player-name').value;
227	    const isPublic = document.querySelector('input[name="game-type"]:checked').value === 'public';
228	    const password = isPublic ? null : document.getElementById('game-password').value;
229	    
230	    if (!client) {
231	        alert('Please enter your player name.');
232	        return;
233	    }
234	    
235	    if (!isPublic && !password) {
236	        alert('Please enter a password for private game.');
237	        return;
238	    }
239	    
240	    fetch('/create_game', { 
241	        method: 'POST',
242	        headers: {'Content-Type': 'application/json'},
243	        body: JSON.stringify({
244	            player_name: client,
245	            is_public: isPublic,
246	            password: password
247	        })
248	    })
249	    .then(response => response.json())
250	    .then(data => {
251	        if (data.success) {
252	            gameId = data.game_id;
253	            console.log(`Game ID: ${gameId}`);
254	            targetAmount = data.target_amount;
255	            console.log(`random amount is: ${targetAmount}`);
256	            joinGame();
257	        } else {
258	            alert('Failed to create game: ' + data.message);
259	        }
260	    })
261	    .catch(error => {
262	        console.error('Error creating game:', error);
263	        alert('Failed to create game.');
264	    });
265	}
266	
267	function leaveGame() {
268	    isLeavingIntentionally = true;
269	    
270	    // Clean up webcam resources
271	    if (webcamManager) {
272	        webcamManager.destroy();
273	        webcamManager = null;
274	    }
275	    
276	    if (gameId && client) {
277	        fetch('/leave_game', {
278	            method: 'POST',
279	            headers: {'Content-Type': 'application/json'},
280	            body: JSON.stringify({game_id: gameId, player_name: client})
281	        })
282	        .then(response => response.json())
283	        .then(data => {
284	            if (data.success) {
285	                socket.emit('leave', {game_id: gameId, player_name: client});
286	                window.location.href = '/';
287	            }
288	        });
289	    }
290	}
291	
292	function joinGame(password = null) {
293	    console.log(`Joining game with ID: ${gameId}`);
294	    
295	    if (gameId && client) {
296	        fetch('/join_game', {
297	            method: 'POST',
298	            headers: {'Content-Type': 'application/json'},
299	            body: JSON.stringify({game_id: gameId, player_name: client, password: password})
300	        })
301	        .then(response => response.json())
302	        .then(data => {
303	            if (data.success) {
304	                console.log(`gameId: ${gameId}, client: ${client}`);
305	                gameState = data.game;
