201	export function gaussianRandom(mean = 0, stdev = 1) {
202	    const u = 1 - Math.random();
203	    const v = Math.random();
204	    const z = Math.sqrt(-2.0 * Math.log(u)) * Math.cos(2.0 * Math.PI * v);
205	    return Math.round(z * stdev + mean);
