481	// Hide the loading spinner overlay
482	export function hideLoading() {
483	    const overlay = document.getElementById('kc-loading-overlay');
484	    if (overlay) overlay.classList.add('kc-hidden');
485	}
486	
487	// Show a toast notification
488	// type: 'info' | 'success' | 'error' | 'warning'
489	export function showToast(message, type = 'info', duration = 2500) {
490	    const toast = document.createElement('div');
491	    toast.className = `kc-toast kc-toast-${type}`;
492	    toast.setAttribute('role', 'alert');
493	    toast.setAttribute('data-test', 'toast');
494	    toast.textContent = message;
495	
496	    document.body.appendChild(toast);
497	
498	    setTimeout(() => {
499	        toast.style.opacity = '0';
500	        setTimeout(() => {
501	            if (document.body.contains(toast)) document.body.removeChild(toast);
502	        }, 350);
503	    }, duration);
504	}
505	
506	// Focus trap for modals — call after appending modal to DOM
507	export function trapFocus(modal) {
508	    const focusable = modal.querySelectorAll(
509	        'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
510	    );
511	    if (!focusable.length) return;
512	    const first = focusable[0];
513	    const last = focusable[focusable.length - 1];
514	
515	    modal.addEventListener('keydown', (e) => {
516	        if (e.key !== 'Tab') return;
517	        if (e.shiftKey) {
518	            if (document.activeElement === first) { last.focus(); e.preventDefault(); }
519	        } else {
520	            if (document.activeElement === last) { first.focus(); e.preventDefault(); }
521	        }
522	    });
523	
524	    first.focus();
525	}
526	```
