471	```
472	and at the bottom:
473	```html
474	<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script>
475	```
476	
477	**Add** in `<head>` (before `<link rel="stylesheet" href="/static/style.css">` if present, or after viewport meta):
478	```html
479	<!-- Tailwind CDN -->
480	<script src="https://cdn.tailwindcss.com"></script>
481	<script>
482	  tailwind.config = {
483	    theme: {
484	      extend: {
485	        colors: {
486	          'kc-accent': '#3b82f6',
487	          'kc-bg':     '#f8fafc',
488	          'kc-surface':'#ffffff',
489	          'kc-text':   '#0f172a',
